[
  {
    "question": "According to Criterion 8.10 in the ICVCM Core Carbon Principles v3, what must the carbon‑crediting program require from a Jurisdictional REDD+ Program proponent under Approach A?",
    "answer": "The carbon‑crediting program shall require the Jurisdictional REDD+ Program proponent to provide documented evidence that they considered carbon credits or results‑based finance related payments prior to the implementation of new mitigation actions or the enhanced implementation of ongoing mitigation actions, and the evidence may include a formal document of intent such as a notification, minutes of meetings of relevant jurisdictional authorities, investment documents, or proof of participation in readiness activities."
  },
  {
    "question": "What are the three validation/verification steps listed for additionality in Jurisdictional REDD+ Programs in the ICVCM Core Carbon Principles v3?",
    "answer": "The steps are: 1) actions or enhanced implementation of ongoing mitigation actions in monitoring reports; 2) validation/verification of the requirements in step 1 by a VVB and/or the carbon‑crediting program; 3) the Jurisdictional REDD+ Program proponent providing evidence to the carbon‑crediting program that expected revenues from carbon credits or results‑based finance are decisive for enabling implementation of the program."
  },
  {
    "question": "If a carbon‑crediting program believes its alternative additionality approaches meet the required threshold, what must it do according to Section 3 of the Assessment Procedure in the ICVCM Core Carbon Principles v3?",
    "answer": "It may submit an explanation of such approaches and all relevant provisions to the ICVCM and shall make that explanation publicly available."
  }
]

[
  {
    "question": "According to Criterion 9.5 of the ICVCM Core Carbon Principles, what duration must the pooled buffer reserve be adequate to compensate for potential reversals in a Jurisdictional REDD+ Program?",
    "answer": "The pooled buffer reserve must be adequate to compensate for potential reversals for a minimum of forty years from the start of the first crediting period."
  },
  {
    "question": "Under Criterion 9.5 of the ICVCM Core Carbon Principles, what must happen to all carbon credits in the pooled buffer reserve contributed by a Jurisdictional REDD+ Program proponent when that proponent leaves the carbon‑crediting program?",
    "answer": "All the carbon credits in the pooled buffer reserve contributed by that Jurisdictional REDD+ Program proponent must be immediately cancelled when that proponent leaves the carbon‑crediting program."
  },
  {
    "question": "What does Table 9.6 of the ICVCM Core Carbon Principles indicate the ICVCM will consider for the next iteration of the assessment framework regarding permanence?",
    "answer": "The ICVCM will consider longer monitoring and compensation periods (e.g., one hundred years) and shifting the monitoring and compensation oversight."
  }
]

[
  {
    "question": "According to the Gold Standard Principles and Requirements, what is the renewal date if the Design Certification Renewal review completes after the last date of the current certification cycle?",
    "answer": "The renewal date shall be the first day after the end date of the current certification cycle."
  },
  {
    "question": "What penalty does the Gold Standard Principles and Requirements impose for a delay in the completion of re‑validation beyond the last date of the current certification cycle?",
    "answer": "Delay shall result in a reduction of any issuance of Certified Products and/or Impact Statements available during the following certification cycle; for example, a delay of 1 year beyond the first cycle shall mean that no Certified Impact Statements shall be issued for the period of delay."
  },
  {
    "question": "What is the standard length of the Design Certification Renewal cycle for projects under the Gold Standard Principles and Requirements?",
    "answer": "A five‑year Design Certification Renewal cycle applies to all projects, though some project types are allowed for automatic renewal for a given number of cycles and/or to remove the need for any or all of the listed assessment items."
  }
]

[
  {
    "question": "According to the ICVCM_Core_Carbon_Principles_v3, what must a carbon‑crediting program do before it can grant carbon credits the Attribute of quantified positive SDG impacts?",
    "answer": "The program must ensure that (1) the SDG impacts of the mitigation activity have been monitored and quantified ex‑post using a method, tool or standard recognised by a CCP‑Eligible carbon‑crediting program; (2) the application of that method, tool or standard demonstrates quantified positive impact for one or more SDGs (other than SDG 13); and (3) the quantification of the positive SDG impacts has been verified by a VVB."
  },
  {
    "question": "Which existing methods or standards are cited in the ICVCM_Core_Carbon_Principles_v3 as examples that carbon‑crediting programs can refer to for quantifying positive SDG impacts?",
    "answer": "The document cites the Gold Standard SDG Impact Tool (operated by the Gold Standard), Sustainable Development Verified Impact Standard (SD Vista) (operated by Verra), Climate, Community & Biodiversity Standards (CCB) (operated by Verra), or other relevant programs."
  },
  {
    "question": "What public‑information requirement does the ICVCM_Core_Carbon_Principles_v3 place on a carbon‑crediting program regarding monetary contributions and carbon credits forwarded to the Adaptation Fund?",
    "answer": "The carbon‑crediting program shall make the information on monetary contributions and/or carbon credits forwarded to the Adaptation Fund publicly available on its website and ensure the information is kept up to date."
  }
]

