[
  {
    "question": "According to the Article6.4_Methodology_Standard, what is the default validity period for standardized baselines and how can it be altered?",
    "answer": "Standardized baselines shall include a default validity period of three years, starting from the date of approval by the Supervisory Body. A host Party may propose a shorter or longer validity period, taking into account the specificity of sectors in which activities are undertaken, and by providing justification for the consideration of the Supervisory Body."
  },
  {
    "question": "In the Article6.4_Methodology_Standard, under what conditions must a default group of facilities be disaggregated, and what criteria may be used for this disaggregation?",
    "answer": "A default group of facilities should be disaggregated when significant dissimilarities exist in the performance of facilities or groups of facilities in the country/region. Disaggregation shall be carried out according to relevant criteria, such as scale of production, installed capacity or age of the facilities."
  },
  {
    "question": "What does the Article6.4_Methodology_Standard state about the impact of an updated standardized baseline on registered activities that are using a previous version?",
    "answer": "An updated standardized baseline shall not impact registered activities applying the previous version up to the end of their current crediting period."
  }
]

[
  {
    "question": "According to VCS Standard v5.0, what is the required timeline for project proponents to address public comments received within the 30‑day public comment period?",
    "answer": "For comments received within the 30‑day public comment period, project proponents must address them before the validation process is finalized."
  },
  {
    "question": "What does VCS Standard v5.0 require project proponents to do regarding a grievance redress mechanism before the project start date?",
    "answer": "Project proponents shall, before the project start date, establish and make publicly available a grievance redress mechanism to address concerns from stakeholders."
  },
  {
    "question": "When major changes to the conditions upon which consent was granted are expected, what actions must project proponents take under VCS Standard v5.0?",
    "answer": "The project proponent shall (1) obtain consent from customary rights holders and IPs as early as possible, and (2) amend the project implementation agreement to reflect the revised terms of consent, where necessary."
  }
]

