  }
]

[
  {
    "question": "According to VCS Standard v5.0, what must a project proponent do when a deviation impacts the applicability of the methodology, additionality, or the appropriateness of the baseline scenario?",
    "answer": "The project proponent shall describe and justify the deviation in a revised version of the project description and in all subsequent monitoring reports, including when the deviation occurred, the reasons for the deviation, and how the deviation impacts the applicability of the methodology, additionality, and/or the appropriateness of the baseline scenario."
  },
  {
    "question": "In VCS Standard v5.0, which guideline is used to determine whether a project description deviation impacts methodology applicability, additionality, or baseline scenario appropriateness?",
    "answer": "The CDM Guidelines on Assessment of Different Types of Changes from the Project Activity as Described in the Registered PDD shall be used."
  },
  {
    "question": "What examples does VCS Standard v5.0 give of deviations that could impact methodology applicability or additionality?",
    "answer": "Examples include a change in project capacity where a different baseline scenario would be more plausible, the applied methodology would no longer be applicable, or there would be a significant impact on the investment analysis used to demonstrate additionality, as well as the addition of new carbon pools or new types of project activities."
  }
]

[
  {
    "question": "According to the ICVCM_Core_Carbon_Principles_v3, what three human rights safeguards must mitigation activity proponents ensure in their activities?",
    "answer": "The carbon-crediting program shall require mitigation activity proponents to ensure that the mitigation activity: 1) avoids discrimination and respects human rights; 2) abides by the International Bill of Human Rights and universal instruments ratified by the host country; 3) takes into account and responds to local stakeholders’ views."
  },
  {
    "question": "In the ICVCM_Core_Carbon_Principles_v3, what are the three gender equality requirements that mitigation activity proponents must provide?",
    "answer": "The carbon-crediting program shall require mitigation activity proponents to ensure that the mitigation activity: 1) provides for equal opportunities in the context of gender; 2) protects against and appropriately responds to violence against women and girls; 3) provides equal pay for equal work."
  },
  {
    "question": "What does the ICVCM_Core_Carbon_Principles_v3 require mitigation activity proponents to confirm in validated design documents regarding safeguards?",
    "answer": "The carbon-crediting program shall require that mitigation activity proponents confirm in validated design documents that the mitigation activity adheres to the above safeguards, or that it has put in place the measures referred to in criterion 7.1 b) 1) above."
  }
]

